examples.code:
from fastapi import FastAPI, HTTPException, status

app = FastAPI(title="Catalogo API", version="2.0.0")

ITEMS = {1: "Laptop", 2: "Teclado"}

@app.get("/items/{item_id}", status_code=status.HTTP_200_OK, tags=["inventario"])
async def get_item(item_id: int) -> dict[str, str]:
    if item_id not in ITEMS:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Item inexistente")
    return {"nombre": ITEMS[item_id]}

